import sys
import json
from functools import lru_cache

class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)

        def run_cost(count: int) -> int:
            if count == 1:
                return 1
            if count < 10:
                return 2
            if count < 100:
                return 3
            return 4

        @lru_cache(maxsize=None)
        def dp(i: int, remaining: int) -> int:
            if i == n or n - i <= remaining:
                return 0

            best = dp(i + 1, remaining - 1) if remaining > 0 else n + 5
            same = 0
            deleted = 0

            for j in range(i, n):
                if s[j] == s[i]:
                    same += 1
                else:
                    deleted += 1

                if deleted > remaining:
                    break

                best = min(best, run_cost(same) + dp(j + 1, remaining - deleted))

            return best

        return dp(0, k)

