#include <stdlib.h>
#include <string.h>

static int n;
static int budget;
static char *text;
static int memo[101][101];

static int run_cost(int count) {
    if (count == 1) return 1;
    if (count < 10) return 2;
    if (count < 100) return 3;
    return 4;
}

static int dp(int i, int remaining) {
    if (i == n || n - i <= remaining) return 0;
    if (memo[i][remaining] != -1) return memo[i][remaining];

    int best = remaining > 0 ? dp(i + 1, remaining - 1) : n + 5;
    int same = 0;
    int deleted = 0;

    for (int j = i; j < n; ++j) {
        if (text[j] == text[i]) ++same;
        else ++deleted;
        if (deleted > remaining) break;
        int candidate = run_cost(same) + dp(j + 1, remaining - deleted);
        if (candidate < best) best = candidate;
    }

    memo[i][remaining] = best;
    return best;
}

static void fill_memo(void) {
    for (int i = 0; i <= 100; ++i)
        for (int j = 0; j <= 100; ++j)
            memo[i][j] = -1;
}

int getLengthOfOptimalCompression(char *s, int k) {
    text = s;
    n = (int)strlen(s);
    budget = k;
    fill_memo();
    return dp(0, budget);
