import java.io.*;
import java.util.*;

class Solution {
    private int n;
    private int[][] memo;
    private String s;

    private int runCost(int count) {
        if (count == 1) return 1;
        if (count < 10) return 2;
        if (count < 100) return 3;
        return 4;
    }

    private int dp(int i, int remaining) {
        if (i == n || n - i <= remaining) return 0;
        if (memo[i][remaining] != -1) return memo[i][remaining];

        int best = remaining > 0 ? dp(i + 1, remaining - 1) : n + 5;
        int same = 0;
        int deleted = 0;

        for (int j = i; j < n; j++) {
            if (s.charAt(j) == s.charAt(i)) same++;
            else deleted++;
            if (deleted > remaining) break;
            best = Math.min(best, runCost(same) + dp(j + 1, remaining - deleted));
        }

        memo[i][remaining] = best;
        return best;
    }

    public int getLengthOfOptimalCompression(String s, int k) {
        this.s = s;
        this.n = s.length();
        this.memo = new int[n + 1][k + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dp(0, k);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        int firstQuote = line.indexOf('"');
        int secondQuote = line.indexOf('"', firstQuote + 1);
        String s = line.substring(firstQuote + 1, secondQuote);
        int comma = line.indexOf(',', secondQuote);
        int k = Integer.parseInt(line.substring(comma + 1, line.length() - 1).trim());
        System.out.println(new Solution().getLengthOfOptimalCompression(s, k));
    }
}

